class Solution:
    def minOperations(self, nums: List[int]) -> List[int]:
        pals = []
        for L in range(1, 14):
            half = (L + 1) // 2
            for h in range(1 << (half - 1), 1 << half):
                b = bin(h)[2:]
                p = b + (b[-2::-1] if L % 2 else b[::-1])
                pals.append(int(p, 2))
        pals.sort()
        res = []
        for x in nums:
            i = bisect.bisect_left(pals, x)
            best = pals[i] - x
            if i > 0:
                best = min(best, x - pals[i - 1])
            res.append(best)
        return res

