class Solution {
public:
    vector<int> minOperations(vector<int>& nums) {
        vector<int> pals;
        for (int L = 1; L <= 13; L++) {
            int half = (L + 1) / 2;
            for (int h = 1 << (half - 1); h < (1 << half); h++) {
                string b = bitset<16>(h).to_string().substr(16 - half);
                string p = b;
                if (L % 2) p += string(b.rbegin() + 1, b.rend());
                else p += string(b.rbegin(), b.rend());
                pals.push_back(stoi(p, nullptr, 2));
            }
        }
        sort(pals.begin(), pals.end());
        vector<int> res;
        for (int x : nums) {
            int i = lower_bound(pals.begin(), pals.end(), x) - pals.begin();
            int best = pals[i] - x;
            if (i > 0) best = min(best, x - pals[i - 1]);
            res.push_back(best);
        }
        return res;
    }
};

