class Solution {
    public int[] minOperations(int[] nums) {
        List<Integer> pals = new ArrayList<>();
        for (int L = 1; L <= 13; L++) {
            int half = (L + 1) / 2;
            for (int h = 1 << (half - 1); h < (1 << half); h++) {
                String b = Integer.toBinaryString(h);
                StringBuilder sb = new StringBuilder(b);
                String rev = sb.reverse().toString();
                String p = (L % 2 == 1) ? b + rev.substring(1) : b + rev;
                pals.add(Integer.parseInt(p, 2));
            }
        }
        Collections.sort(pals);
        int[] res = new int[nums.length];
        for (int qi = 0; qi < nums.length; qi++) {
            int x = nums[qi];
            int i = Collections.binarySearch(pals, x);
            if (i < 0) i = -(i + 1);
            int best = pals.get(i) - x;
            if (i > 0) best = Math.min(best, x - pals.get(i - 1));
            res[qi] = best;
        }
        return res;
    }
}

