var minOperations = function(nums) {
    const pals = [];
    for (let L = 1; L <= 13; L++) {
        const half = (L + 1) >> 1;
        for (let h = 1 << (half - 1); h < (1 << half); h++) {
            const b = h.toString(2);
            const rev = [...b].reverse().join('');
            const p = (L % 2 === 1) ? b + rev.slice(1) : b + rev;
            pals.push(parseInt(p, 2));
        }
    }
    pals.sort((a, b) => a - b);
    return nums.map(x => {
        let lo = 0, hi = pals.length - 1;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (pals[mid] < x) lo = mid + 1; else hi = mid;
        }
        let best = pals[lo] - x;
        if (lo > 0) best = Math.min(best, x - pals[lo - 1]);
        return best;
    });
};

