class Solution:
    def minOperations(self, nums: List[int]) -> List[int]:
        def nearest(x):
            b = bin(x)[2:]
            L = len(b)
            best = float('inf')
            for hf in {b[:(L + 1) // 2], b[:L // 2]}:
                if not hf:
                    continue
                h = int(hf, 2)
                for hh in (h - 1, h, h + 1):
                    if hh <= 0:
                        continue
                    t = bin(hh)[2:]
                    if len(t) != len(hf):
                        continue
                    p = t + (t[-2::-1] if L % 2 else t[::-1])
                    best = min(best, abs(int(p, 2) - x))
            return best
        return [nearest(x) for x in nums]

