class Solution {
public:
    vector<int> minOperations(vector<int>& nums) {
        vector<int> res;
        for (int x : nums) {
            string b = bitset<16>(x).to_string().substr(16 - __builtin_clz(x) - (x ? 0 : 0));
            b = bitset<16>(x).to_string(); b.erase(0, b.find('1'));
            int L = b.size();
            int best = INT_MAX;
            set<string> halves = {b.substr(0, (L + 1) / 2), b.substr(0, L / 2)};
            for (const string& hf : halves) {
                if (hf.empty()) continue;
                int h = stoi(hf, nullptr, 2);
                for (int dh = -1; dh <= 1; dh++) {
                    int hh = h + dh;
                    if (hh <= 0) continue;
                    string t = bitset<16>(hh).to_string();
                    t.erase(0, t.find('1'));
                    if ((int)t.size() != (int)hf.size()) continue;
                    string r = t; reverse(r.begin(), r.end());
                    string p = (L % 2) ? t + r.substr(1) : t + r;
                    best = min(best, abs(stoi(p, nullptr, 2) - x));
                }
            }
            res.push_back(best);
        }
        return res;
    }
};

