class Solution {
    public int[] minOperations(int[] nums) {
        int[] res = new int[nums.length];
        for (int qi = 0; qi < nums.length; qi++) {
            String b = Integer.toBinaryString(nums[qi]);
            int L = b.length();
            int best = Integer.MAX_VALUE;
            java.util.Set<String> halves = new java.util.HashSet<>();
            halves.add(b.substring(0, (L + 1) / 2));
            halves.add(b.substring(0, L / 2));
            for (String hf : halves) {
                if (hf.isEmpty()) continue;
                int h = Integer.parseInt(hf, 2);
                for (int dh = -1; dh <= 1; dh++) {
                    int hh = h + dh;
                    if (hh <= 0) continue;
                    String t = Integer.toBinaryString(hh);
                    if (t.length() != hf.length()) continue;
                    String r = new StringBuilder(t).reverse().toString();
                    String p = (L % 2 == 1) ? t + r.substring(1) : t + r;
                    best = Math.min(best, Math.abs(Integer.parseInt(p, 2) - nums[qi]));
                }
            }
            res[qi] = best;
        }
        return res;
    }
}

